use serde_json::Value;fn actual(p:&[u8])->Value{serde_json::from_str(&serde_json::to_string(&kanpo_parser::analyze_item(&kanpo_parser::page_inputs(p).unwrap())).unwrap()).unwrap()}
#[test]fn page_20260803g001740151(){let a=actual(include_bytes!("archive/pages/20260803g00174/20260803g001740151.pdf"));assert!(a["text"].as_str().unwrap().contains("辻田　広人"));assert_eq!(a["pages"][0]["words"][526]["text"],"辻田");let e:Value=serde_json::from_str(include_str!("expected/tsuji_source_glyphs/20260803g001740151-source-word-expected.json")).unwrap();assert!(a==e,"whole Analysis must preserve every other source Word/owner/Article/Doc");}
#[test]fn page_20260806g001770082(){let a=actual(include_bytes!("archive/pages/20260806g00177/20260806g001770082.pdf"));assert!(a["text"].as_str().unwrap().contains("辻　潤一郎"));assert_eq!(a["pages"][0]["words"][56]["text"],"辻");let e:Value=serde_json::from_str(include_str!("expected/tsuji_source_glyphs/20260806g001770082-source-word-expected.json")).unwrap();assert!(a==e,"whole Analysis must preserve every other source Word/owner/Article/Doc");}
