#[test]fn merger_source_word_groups_announcement_before_its_two_bs(){let a=actual(include_bytes!("archive/pages/20260730g00171/20260730g001710163.pdf"));let e:Value=serde_json::from_str(include_str!("expected/tsuji_source_glyphs/20260730g001710163-source-order-expected.json")).unwrap();let groups=|v:&Value|v["pages"][0]["regions"][0]["lines"].as_array().unwrap().iter().map(|l|l["words"].clone()).collect::<Vec<_>>();assert_eq!(groups(&a),groups(&e),"19 announcement lines must precede their two BS; all old source-word groups/internal order remain exact");}

#[test]fn merger_full_analysis_native_name_and_source_proven_flow(){let a=actual(include_bytes!("archive/pages/20260730g00171/20260730g001710163.pdf"));let e:Value=serde_json::from_str(include_str!("expected/tsuji_source_glyphs/20260730g001710163-source-order-expected.json")).unwrap();assert!(a==e,"full Analysis must equal source-derived 19-line rotation; all 8 tables/other frames/Article+Doc exact");}

